import React from 'react'
import { ProCard } from '@ant-design/pro-components'
import { Button, Card, Select, Space, Tag } from 'antd'
import { AppstoreOutlined, DeleteOutlined, InfoCircleOutlined, PlusOutlined } from '@ant-design/icons'
import { ProFormInstance } from '@ant-design/pro-components'
import type { SiteTypes } from '@/apis/admin/site'
import SlotStatsPanel, { SlotStats } from '../SlotStatsPanel'
import SlotStatsDisplay from '../SlotStatsDisplay'

// 副柜配置类型
export interface SubCabinetConfig {
  id: number
  /** 规格ID（对应 DeviceCabinetSpecDto.id） */
  template: number
}

export interface CabinetStats {
  main: { name: string; big: number; med: number; small: number } | null
  big: number
  med: number
  small: number
  total: number
  subCount: number
}

interface CabinetConfigSectionProps {
  formRef: React.RefObject<ProFormInstance | undefined>
  /** 主柜规格ID（对应 DeviceCabinetSpecDto.id） */
  mainCabinetType?: number
  subCabinets: SubCabinetConfig[]
  isEditMode: boolean
  /** 柜子类型列表（主柜和副柜共用） */
  cabinetTypes: SiteTypes.DeviceCabinetSpecDto[]
  onMainCabinetTypeChange?: (value: number) => void
  onAddSubCabinet: () => void
  onRemoveSubCabinet: (id: number) => void
  onUpdateSubCabinetTemplate: (id: number, template: number) => void
}

const CabinetConfigSection: React.FC<CabinetConfigSectionProps> = ({
  mainCabinetType,
  subCabinets,
  isEditMode,
  cabinetTypes,
  onMainCabinetTypeChange,
  onAddSubCabinet,
  onRemoveSubCabinet,
  onUpdateSubCabinetTemplate
}) => {
  // 计算格口统计
  const getSlotStats = (): CabinetStats => {
    const mainType = mainCabinetType ? cabinetTypes.find(t => t.id === mainCabinetType) : null

    let totalBig = mainType?.bigGrid || 0
    let totalMed = mainType?.middleGrid || 0
    let totalSmall = mainType?.smallGrid || 0

    subCabinets.forEach(cabinet => {
      const spec = cabinetTypes.find(t => t.id === cabinet.template)
      if (spec) {
        totalBig += spec.bigGrid
        totalMed += spec.middleGrid
        totalSmall += spec.smallGrid
      }
    })

    return {
      main: mainType ? { name: mainType.specName, big: mainType.bigGrid, med: mainType.middleGrid, small: mainType.smallGrid } : null,
      big: totalBig,
      med: totalMed,
      small: totalSmall,
      total: totalBig + totalMed + totalSmall,
      subCount: subCabinets.length
    }
  }

  const stats = getSlotStats()

  // 生成 Select 选项的 label
  const getOptionLabel = (spec: SiteTypes.DeviceCabinetSpecDto) =>
    `${spec.specName}：大${spec.bigGrid} / 中${spec.middleGrid} / 小${spec.smallGrid}（共${spec.totalGrid}格口）`

  // 柜机规格选项列表（主柜和副柜共用）
  const specOptions = cabinetTypes.map(spec => ({
    label: getOptionLabel(spec),
    value: spec.id
  }))

  // 转换为 SlotStatsPanel 需要的格式
  const slotStats: SlotStats = {
    big: stats.big,
    med: stats.med,
    small: stats.small,
    total: stats.total,
    subCount: stats.subCount
  }

  return (
    <ProCard
      title={
        <Space>
          <AppstoreOutlined style={{ color: '#1890ff' }} />
          格口配置
        </Space>
      }
      bordered
      style={{ marginBottom: 24 }}
    >
      <p style={{ fontSize: 13, color: '#666', marginBottom: 16 }}>
        <InfoCircleOutlined style={{ marginRight: 4 }} />
        每个设备必须配置一个主柜，可根据需要添加多个副柜
      </p>

      {/* 格口配置 Grid 布局 */}
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(320px, 1fr))', gap: 16, marginBottom: 16 }}>
        {/* 主柜配置 */}
        <Card
          title={
            <Space>
              <Tag color="blue">
                <AppstoreOutlined /> 主柜
              </Tag>
              <span style={{ fontSize: 13, color: '#666' }}>必选，主控制柜</span>
            </Space>
          }
          bordered
          style={{ background: '#f6ffed' }}
        >
          <Select
            value={mainCabinetType}
            onChange={value => onMainCabinetTypeChange?.(value)}
            placeholder="请选择格口模板"
            disabled={!!isEditMode}
            style={{ width: '100%', marginBottom: 10 }}
          >
            {specOptions.map(option => (
              <Select.Option key={option.value} value={option.value}>
                {option.label}
              </Select.Option>
            ))}
          </Select>
          {stats.main && (
            <SlotStatsDisplay
              big={stats.main.big}
              med={stats.main.med}
              small={stats.main.small}
              background="#fff"
            />
          )}
        </Card>

        {/* 副柜列表 */}
        {subCabinets.map((cabinet, index) => {
          const spec = cabinetTypes.find(t => t.id === cabinet.template)
          return (
            <Card
              key={cabinet.id}
              title={
                <Space>
                  <Tag color="orange">
                    <AppstoreOutlined /> 副柜 {index + 1}
                  </Tag>
                  <span style={{ fontSize: 13, color: '#666' }}>扩展存储柜</span>
                </Space>
              }
              bordered
              extra={
                <Button
                  type="text"
                  danger
                  icon={<DeleteOutlined />}
                  onClick={() => onRemoveSubCabinet(cabinet.id)}
                >
                  删除
                </Button>
              }
            >
              <Select
                value={cabinet.template}
                onChange={value => onUpdateSubCabinetTemplate(cabinet.id, value)}
                style={{ width: '100%', marginBottom: 10 }}
              >
                {specOptions.map(option => (
                  <Select.Option key={option.value} value={option.value}>
                    {option.label}
                  </Select.Option>
                ))}
              </Select>
              {spec && (
                <SlotStatsDisplay
                  big={spec.bigGrid}
                  med={spec.middleGrid}
                  small={spec.smallGrid}
                />
              )}
            </Card>
          )
        })}
      </div>

      {/* 添加副柜按钮 */}
      <Button
        type="dashed"
        block
        icon={<PlusOutlined />}
        onClick={onAddSubCabinet}
        style={{ marginBottom: 16 }}
      >
        添加副柜
      </Button>

      {/* 总计统计 */}
      <SlotStatsPanel stats={slotStats} />
    </ProCard>
  )
}

export default CabinetConfigSection
