import { useState } from 'react'
import { getJdAreaList, SiteTypes } from '@/apis/admin/site'
import { AMapPickerResult } from '@/components/AMapPicker'

// 区域数据缓存（组件级别缓存）
const areaCache = {
  province: {
    data: null as SiteTypes.JdAreaDataDto[] | null,
    promise: null as Promise<SiteTypes.JdAreaDataDto[]> | null
  },
  city: new Map<
    number,
    {
      data: SiteTypes.JdAreaDataDto[] | null
      promise: Promise<SiteTypes.JdAreaDataDto[]> | null
    }
  >(),
  district: new Map<
    number,
    {
      data: SiteTypes.JdAreaDataDto[] | null
      promise: Promise<SiteTypes.JdAreaDataDto[]> | null
    }
  >()
}

export interface UseAreaCascadeReturn {
  provinceList: SiteTypes.JdAreaDataDto[]
  cityList: SiteTypes.JdAreaDataDto[]
  districtList: SiteTypes.JdAreaDataDto[]
  selectedProvince: number | undefined
  selectedCity: number | undefined
  setSelectedProvince: (id: number | undefined) => void
  setSelectedCity: (id: number | undefined) => void
  setCityList: (list: SiteTypes.JdAreaDataDto[]) => void
  setDistrictList: (list: SiteTypes.JdAreaDataDto[]) => void
  loadProvinceList: () => Promise<SiteTypes.JdAreaDataDto[]>
  loadCityList: (provinceId: number) => Promise<SiteTypes.JdAreaDataDto[]>
  loadDistrictList: (cityId: number) => Promise<SiteTypes.JdAreaDataDto[]>
  matchProvinceCityDistrict: (result: AMapPickerResult) => Promise<{
    provinceId?: number
    cityId?: number
    districtId?: number
  } | null>
  handleProvinceChange: (value: number, formRef?: any) => Promise<void>
  handleCityChange: (value: number, formRef?: any) => Promise<void>
}

export const useAreaCascade = (): UseAreaCascadeReturn => {
  const [provinceList, setProvinceList] = useState<SiteTypes.JdAreaDataDto[]>([])
  const [cityList, setCityList] = useState<SiteTypes.JdAreaDataDto[]>([])
  const [districtList, setDistrictList] = useState<SiteTypes.JdAreaDataDto[]>([])
  const [selectedProvince, setSelectedProvince] = useState<number | undefined>()
  const [selectedCity, setSelectedCity] = useState<number | undefined>()

  // 加载省份数据（带缓存）
  const loadProvinceList = async (): Promise<SiteTypes.JdAreaDataDto[]> => {
    // 如果已有数据，直接返回
    if (areaCache.province.data) {
      setProvinceList(areaCache.province.data)
      return areaCache.province.data
    }

    // 如果请求正在进行中，返回现有的 promise
    if (areaCache.province.promise) {
      const list = await areaCache.province.promise
      setProvinceList(list)
      return list
    }

    // 创建新的请求 promise
    const fetchPromise = (async () => {
      try {
        const result = await getJdAreaList({ fid: 4744 })
        const list = result.data?.list || []
        // 缓存数据
        areaCache.province.data = list
        setProvinceList(list)
        return list
      } catch (error) {
        console.error('获取省份数据失败:', error)
        return []
      } finally {
        // 清理 promise 引用
        areaCache.province.promise = null
      }
    })()

    // 缓存 promise
    areaCache.province.promise = fetchPromise
    return fetchPromise
  }

  // 加载城市数据（带缓存）
  const loadCityList = async (provinceId: number): Promise<SiteTypes.JdAreaDataDto[]> => {
    // 检查缓存
    const cached = areaCache.city.get(provinceId)
    if (cached?.data) {
      setCityList(cached.data)
      return cached.data
    }
    if (cached?.promise) {
      const list = await cached.promise
      setCityList(list)
      return list
    }

    // 创建新的请求
    const fetchPromise = (async () => {
      try {
        const result = await getJdAreaList({ fid: provinceId })
        const list = result.data?.list || []
        setCityList(list)
        // 更新缓存
        areaCache.city.set(provinceId, { data: list, promise: null })
        return list
      } catch (error) {
        console.error('获取城市数据失败:', error)
        areaCache.city.set(provinceId, { data: [], promise: null })
        return []
      }
    })()

    // 缓存 promise
    areaCache.city.set(provinceId, { data: null, promise: fetchPromise })
    return fetchPromise
  }

  // 加载区域数据（带缓存）
  const loadDistrictList = async (cityId: number): Promise<SiteTypes.JdAreaDataDto[]> => {
    // 检查缓存
    const cached = areaCache.district.get(cityId)
    if (cached?.data) {
      setDistrictList(cached.data)
      return cached.data
    }
    if (cached?.promise) {
      const list = await cached.promise
      setDistrictList(list)
      return list
    }

    // 创建新的请求
    const fetchPromise = (async () => {
      try {
        const result = await getJdAreaList({ fid: cityId })
        const list = result.data?.list || []
        setDistrictList(list)
        // 更新缓存
        areaCache.district.set(cityId, { data: list, promise: null })
        return list
      } catch (error) {
        console.error('获取区域数据失败:', error)
        areaCache.district.set(cityId, { data: [], promise: null })
        return []
      }
    })()

    // 缓存 promise
    areaCache.district.set(cityId, { data: null, promise: fetchPromise })
    return fetchPromise
  }

  // 匹配省市区
  const matchProvinceCityDistrict = async (result: AMapPickerResult) => {
    const { province, city, district } = result
    // 获取省份数据（优先使用缓存或加载）
    const provinces = await loadProvinceList()

    // 查找并设置省份
    const matchedProvince = provinces.find(
      p => p.name === province || p.name === province + '省' || province.includes(p.name)
    )
    if (!matchedProvince) {
      return null
    }

    setSelectedProvince(matchedProvince.id)

    // 加载城市数据并查找匹配
    const cities = await loadCityList(matchedProvince.id)
    const matchedCity = cities.find(
      c => c.name === city || c.name === city + '市' || city.includes(c.name)
    )
    if (!matchedCity) {
      return { provinceId: matchedProvince.id }
    }

    setSelectedCity(matchedCity.id)

    // 加载区域数据并查找匹配
    const districts = await loadDistrictList(matchedCity.id)
    const matchedDistrict = districts.find(
      d => d.name === district || d.name === district + '区' || district.includes(d.name)
    )

    return {
      provinceId: matchedProvince.id,
      cityId: matchedCity.id,
      districtId: matchedDistrict?.id
    }
  }

  // 省份变化
  const handleProvinceChange = async (value: number, formRef?: any) => {
    setSelectedProvince(value)
    setCityList([])
    if (formRef) {
      formRef.current?.setFieldsValue({
        cityId: undefined,
        areaId: undefined
      })
    }
    await loadCityList(value)
  }

  // 城市变化
  const handleCityChange = async (value: number, formRef?: any) => {
    setSelectedCity(value)
    if (formRef) {
      formRef.current?.setFieldsValue({
        areaId: undefined
      })
    }
    await loadDistrictList(value)
  }

  return {
    provinceList,
    cityList,
    districtList,
    selectedProvince,
    selectedCity,
    setSelectedProvince,
    setSelectedCity,
    setCityList,
    setDistrictList,
    loadProvinceList,
    loadCityList,
    loadDistrictList,
    matchProvinceCityDistrict,
    handleProvinceChange,
    handleCityChange
  }
}
