import { useEffect, useRef, useState } from 'react'
import { useNavigate, useParams } from 'react-router-dom'
import {
  PageContainer,
  ProCard,
  ProForm,
  ProFormInstance,
  ProFormText,
  ProFormSelect
} from '@ant-design/pro-components'
import { Button, message, Space, Tag, Row, Col, Form } from 'antd'
import {
  ArrowLeftOutlined,
  SaveOutlined,
  EnvironmentOutlined,
  CloseOutlined,
  InfoCircleOutlined,
  AppstoreOutlined
} from '@ant-design/icons'
import { editDevice, getDeviceInfo, DeviceManagementTypes } from '@/apis/admin/device-management'
import { getSysCommunityList, SystemConfigTypes } from '@/apis/admin/system-config'
import AMapPicker from '@/components/AMapPicker'
import AreaCascader, { AreaCascaderRef } from '@/components/AreaCascader'
import { ResultEnum } from '@/utils/enums/httpEnum'
import { get as getZipCode } from '@tombcato/china-zipcode-data'

import { useAreaCascade } from './hooks/useAreaCascade'
import CabinetConfigSection, { SubCabinetConfig } from './components/CabinetConfigSection'
import { DEVICE_MODEL_OPTIONS } from '@/constants'
import { useDeviceCabinetSpec } from '@/hooks/useDeviceCabinetSpec'

const DeviceEdit: React.FC = () => {
  const navigate = useNavigate()
  const { id: deviceId } = useParams<{ id: string }>()
  const formRef = useRef<ProFormInstance>()
  const mapPickerRef = useRef<any>(null)
  const areaCascaderRef = useRef<AreaCascaderRef>(null)

  const [loading, setLoading] = useState(false)
  const [communityList, setCommunityList] = useState<SystemConfigTypes.SysCommunityListDto[]>([])
  const [subCabinets, setSubCabinets] = useState<SubCabinetConfig[]>([])
  const [mainCabinetType, setMainCabinetType] = useState<number | undefined>(undefined)

  // 使用柜子规格 hook（动态获取）
  const { specs } = useDeviceCabinetSpec()

  // 省市区选择值（string[] 格式）
  const [areaValues, setAreaValues] = useState<string[]>([])
  const { matchProvinceCityDistrict } = useAreaCascade()

  // 加载小区数据（根据省市区筛选）
  const loadCommunityList = async (provinceId?: number, cityId?: number, areaId?: number) => {
    try {
      const res = await getSysCommunityList({ provinceId, cityId, areaId })
      if (res.code === ResultEnum.SUCCESS && res.data?.list) {
        setCommunityList(res.data.list)
      }
    } catch (e) {
      console.error('获取小区列表失败:', e)
    }
  }

  // 获取设备详情
  const fetchDeviceInfo = async () => {
    if (!deviceId) {
      message.error('设备ID不能为空')
      navigate('/device/list')
      return
    }
    try {
      setLoading(true)
      const res = await getDeviceInfo(Number(deviceId))
      if (res.code === ResultEnum.SUCCESS && res.data?.list?.length > 0) {
        const deviceData = res.data.list[0].deviceBaseData
        formRef.current?.setFieldsValue({
          imei: deviceData.imei,
          deviceName: deviceData.deviceName,
          deviceModel: deviceData.deviceModel,
          installLocation: deviceData.installLocation,
          postalCode: '',
          longitude: deviceData.longitude,
          latitude: deviceData.latitude
        })
        // 从 mainCabinetSpecData 获取主柜规格ID
        const mainSpecId = deviceData.mainCabinetSpecData?.[0]?.specId
        setMainCabinetType(mainSpecId)

        // 设置省市区级联值
        if (deviceData.provinceId && deviceData.cityId && deviceData.areaId) {
          setAreaValues([
            String(deviceData.provinceId),
            String(deviceData.cityId),
            String(deviceData.areaId)
          ])
        }
        // 设置表单值
        formRef.current?.setFieldsValue({
          provinceId: deviceData.provinceId,
          cityId: deviceData.cityId,
          areaId: deviceData.areaId,
          communityId: deviceData.communityId
        })

        // 如果已有经纬度，设置地图中心点
        if (deviceData.longitude && deviceData.latitude && mapPickerRef.current) {
          mapPickerRef.current.setCenter(deviceData.longitude, deviceData.latitude)
        }
      } else {
        message.error('获取设备详情失败')
      }
    } catch (e) {
      console.error('获取设备详情失败:', e)
      message.error('获取设备详情失败')
    } finally {
      setLoading(false)
    }
  }

  useEffect(() => {
    fetchDeviceInfo()
  }, [deviceId])

  // 处理地图选点
  const handleMapSelect = async (result: any) => {
    // 填充经纬度
    formRef.current?.setFieldsValue({
      longitude: result.longitude,
      latitude: result.latitude,
      installLocation: result.address
    })
    if (result?.adcode) {
      const postalCode = await getZipCode(result.adcode)
      formRef.current?.setFieldsValue({ postalCode: postalCode?.zipCode })
    }

    // 匹配省市区
    const matched = await matchProvinceCityDistrict(result)
    if (matched?.provinceId && matched?.cityId && matched?.districtId) {
      // 先加载 AreaCascader 的省市区数据，确保能显示中文名称
      if (areaCascaderRef.current) {
        // 加载省级数据
        await areaCascaderRef.current.loadAreaData(4744, 0)
        // 加载市级数据
        await areaCascaderRef.current.loadAreaData(matched.provinceId, 1)
        // 加载区级数据
        await areaCascaderRef.current.loadAreaData(matched.cityId, 2)
      }

      // 判断是否为直辖市
      const isMunicipality = [1, 2, 3, 4].includes(matched.provinceId)
      if (isMunicipality) {
        // 直辖市格式：[省ID, 省ID, 区ID]
        setAreaValues([
          String(matched.provinceId),
          String(matched.provinceId),
          String(matched.districtId)
        ])
      } else {
        // 普通城市格式：[省ID, 市ID, 区ID]
        setAreaValues([
          String(matched.provinceId),
          String(matched.cityId),
          String(matched.districtId)
        ])
      }

      formRef.current?.setFieldsValue({
        provinceId: matched.provinceId,
        cityId: matched.cityId,
        areaId: matched.districtId
      })
    }
  }

  // 添加副柜
  const addSubCabinet = () => {
    const defaultSpecId = specs[0]?.id
    if (defaultSpecId) {
      setSubCabinets([...subCabinets, { id: Date.now(), template: defaultSpecId }])
    }
  }

  // 删除副柜
  const removeSubCabinet = (id: number) => {
    setSubCabinets(subCabinets.filter(c => c.id !== id))
  }

  // 更新副柜模板
  const updateSubCabinetTemplate = (id: number, template: number) => {
    setSubCabinets(subCabinets.map(c => (c.id === id ? { ...c, template } : c)))
  }

  // 提交表单
  const handleSubmit = async () => {
    const values = await formRef.current?.validateFields()
    if (!values) {
      return
    }

    if (!mainCabinetType) {
      message.error('请选择主柜类型')
      return
    }

    if (!deviceId) {
      message.error('设备ID不能为空')
      return
    }

    try {
      setLoading(true)
      // 转换主柜规格数据
      // cabinetId: -1 表示新加，specId 从 cabinetTypes 根据选择的类型获取
      const mainCabinetSpecData: DeviceManagementTypes.CabinetSpecDataInp[] = mainCabinetType
        ? [
            {
              cabinetId: -1, // -1 表示新加
              specId: mainCabinetType // 直接使用选择的柜子类型值作为 specId
            }
          ]
        : []

      // 转换副柜规格数据（如果有）
      const subCabinetSpecData: DeviceManagementTypes.CabinetSpecDataInp[] = subCabinets.map(
        (cabinet, index) => ({
          cabinetId: -(index + 2), // 使用负数区分不同的副柜 (-2, -3, -4...)
          specId: cabinet.template // 直接取规格ID
        })
      )

      const editData: DeviceManagementTypes.EditDeviceReq = {
        deviceName: values.deviceName,
        deviceModel: values.deviceModel,
        postalCode: values.postalCode || '',
        installLocation: values.installLocation,
        mainCabinetSpecData,
        provinceId: values.provinceId,
        cityId: values.cityId,
        areaId: values.areaId,
        communityId: values.communityId || 0,
        longitude: values.longitude || 0,
        latitude: values.latitude || 0,
        ...(subCabinetSpecData.length > 0 ? { subCabinetSpecData } : {})
      }
      const res = await editDevice(Number(deviceId), editData)
      if (res.code === ResultEnum.SUCCESS) {
        message.success('设备信息修改成功')
        navigate('/device/list')
      } else {
        message.error('设备信息修改失败')
      }
    } catch (e) {
      console.error('提交失败:', e)
      message.error('操作失败')
    } finally {
      setLoading(false)
    }
  }

  return (
    <PageContainer
      header={{
        title: (
          <Space>
            <Button
              type="text"
              icon={<ArrowLeftOutlined />}
              onClick={() => navigate('/device/list')}
            >
              返回设备列表
            </Button>
            <span style={{ fontSize: 20, fontWeight: 600 }}>编辑设备</span>
            <Tag color="orange" icon={<InfoCircleOutlined />}>
              编辑模式
            </Tag>
          </Space>
        ),
        breadcrumb: undefined
      }}
    >
      <ProCard bordered>
        <ProForm
          formRef={formRef}
          submitter={false}
          layout="horizontal"
          labelCol={{ span: 4 }}
          wrapperCol={{ span: 14 }}
          loading={loading}
        >
          {/* 地图定位辅助区 */}
          <ProCard
            title={
              <Space>
                <EnvironmentOutlined style={{ color: '#1890ff' }} />
                地图定位辅助
              </Space>
            }
            bordered
            style={{ marginBottom: 24 }}
          >
            <AMapPicker
              ref={mapPickerRef}
              onSelect={handleMapSelect}
              disabled={false}
              height={360}
            />
            <p style={{ fontSize: 12, color: '#666', marginTop: 8 }}>
              <InfoCircleOutlined style={{ marginRight: 4 }} />
              点击地图选点或搜索地址，可自动填充下方表单字段
            </p>
          </ProCard>

          {/* 基本信息 */}
          <ProCard
            title={
              <Space>
                <AppstoreOutlined style={{ color: '#1890ff' }} />
                基本信息
              </Space>
            }
            bordered
            style={{ marginBottom: 24 }}
          >
            <Row gutter={24}>
              <Col span={12}>
                <ProFormText
                  name="imei"
                  label="设备编号"
                  placeholder="请输入设备编号"
                  rules={[{ required: true, message: '请输入设备编号' }]}
                  disabled
                />
              </Col>
              <Col span={12}>
                <ProFormText
                  name="deviceName"
                  label="设备名称"
                  placeholder="请输入设备名称，如 A栋1号柜"
                  rules={[{ required: true, message: '请输入设备名称' }]}
                />
              </Col>
            </Row>

            <Row gutter={24}>
              <Col span={12}>
                <ProFormSelect
                  name="deviceModel"
                  label="设备型号"
                  placeholder="请选择设备型号"
                  rules={[{ required: true, message: '请选择设备型号' }]}
                  options={DEVICE_MODEL_OPTIONS}
                />
              </Col>
              <Col span={12}>
                <ProFormText name="postalCode" label="邮编" placeholder="请输入邮编" />
              </Col>
            </Row>

            <Row gutter={24}>
              <Col span={12}>
                <ProFormText name="longitude" label="经度" placeholder="经度" disabled />
              </Col>
              <Col span={12}>
                <ProFormText name="latitude" label="纬度" placeholder="纬度" disabled />
              </Col>
            </Row>
          </ProCard>

          {/* 地址信息 */}
          <ProCard
            title={
              <Space>
                <EnvironmentOutlined style={{ color: '#1890ff' }} />
                地址信息
              </Space>
            }
            bordered
            style={{ marginBottom: 24 }}
          >
            <Row gutter={24}>
              <Col span={12}>
                <Form.Item
                  label="省市区"
                  required
                  rules={[{ required: true, message: '请选择省市区' }]}
                >
                  <AreaCascader
                    ref={areaCascaderRef}
                    value={areaValues}
                    onChange={({ values }) => {
                      setAreaValues(values)
                      // 转换为 number 并设置表单值
                      const provinceId = parseInt(values[0])
                      const areaId = parseInt(values[2])
                      // 判断是否为直辖市，如果是则 cityId = provinceId
                      const isMunicipality = [1, 2, 3, 4].includes(provinceId)
                      const cityId = isMunicipality ? provinceId : parseInt(values[1])
                      formRef.current?.setFieldsValue({
                        provinceId,
                        cityId,
                        areaId
                      })
                      // 加载该区县下的小区
                      if (values.length === 3) {
                        loadCommunityList(provinceId, cityId, areaId)
                        // 清空小区选择
                        formRef.current?.setFieldsValue({ communityId: undefined })
                      }
                    }}
                    placeholder="请选择省市区"
                  />
                </Form.Item>
              </Col>
              <Col span={12}>
                <ProFormSelect
                  name="communityId"
                  label="小区"
                  placeholder={areaValues.length === 3 ? '请选择小区' : '请先选择省市区'}
                  options={communityList.map(c => ({ label: c.communityName, value: c.id }))}
                  fieldProps={{
                    showSearch: true,
                    disabled: areaValues.length !== 3
                  }}
                />
              </Col>
            </Row>

            <Row gutter={24}>
              <Col span={24}>
                <ProFormText
                  name="installLocation"
                  label="详细地址"
                  labelCol={{ span: 2 }}
                  placeholder="请输入详细地址，包含街道、门牌号等"
                  rules={[{ required: true, message: '请输入详细地址' }]}
                />
              </Col>
            </Row>
          </ProCard>

          {/* 格口配置 */}
          <CabinetConfigSection
            formRef={formRef}
            mainCabinetType={mainCabinetType}
            subCabinets={subCabinets}
            isEditMode={true}
            cabinetTypes={specs}
            onMainCabinetTypeChange={setMainCabinetType}
            onAddSubCabinet={addSubCabinet}
            onRemoveSubCabinet={removeSubCabinet}
            onUpdateSubCabinetTemplate={updateSubCabinetTemplate}
          />

          {/* 提交按钮 */}
          <div style={{ display: 'flex', gap: 8, justifyContent: 'center' }}>
            <Button
              type="primary"
              icon={<SaveOutlined />}
              size="large"
              onClick={handleSubmit}
              loading={loading}
            >
              保存修改
            </Button>
            <Button icon={<CloseOutlined />} size="large" onClick={() => navigate('/device/list')}>
              返回
            </Button>
          </div>
        </ProForm>
      </ProCard>
    </PageContainer>
  )
}

export default DeviceEdit
