import { useEffect, useRef, useState, forwardRef, useImperativeHandle } from 'react'
import { Card, Input, Space, message } from 'antd'
import {
  LoadingOutlined,
  SearchOutlined
} from '@ant-design/icons'
import AMapLoader from '@amap/amap-jsapi-loader'
import type {
  AMapAddressComponent,
  AMapRegeoResult,
  AMapPOIResult,
  AMapDistrictResult,
  AMapPickerResult,
  AMapPickerProps
} from './types'
//  高德地图 WEB API Key（从环境变量读取）
const AMAP_WEB_API_KEY = import.meta.env.VITE_AMAP_WEB_API_KEY || ''
// 高德地图 JS API Key（从环境变量读取）
const AMAP_JS_API_KEY = import.meta.env.VITE_AMAP_JS_API_KEY || ''
// 安全密钥（从环境变量读取，仅用于开发环境直连模式）
const securityJsCode = import.meta.env.VITE_AMAP_SECURITY_JS_CODE || ''
// Nginx 代理地址（生产环境推荐）
const AMAP_SERVICE_HOST = import.meta.env.VITE_AMAP_SERVICE_HOST || ''

// 重新导出类型，方便外部使用
export type {
  AMapAddressComponent,
  AMapRegeoResult,
  AMapPOIResult,
  AMapDistrictResult,
  AMapPickerResult,
  AMapPickerProps
}

// 判断是否使用代理模式
const isProxyMode = () => !!AMAP_SERVICE_HOST

// 获取 API 基础 URL
const getApiBaseUrl = () => {
  if (isProxyMode()) {
    return AMAP_SERVICE_HOST
  }
  return 'https://restapi.amap.com'
}

// 配置安全策略（必须在加载地图前设置）
const setupSecurityConfig = () => {
  const baseConfig = {
    // 禁用日志上报，避免浏览器扩展拦截导致的控制台错误
    debug: false
  }

  if (isProxyMode()) {
    // 生产环境：使用 Nginx 代理模式
    window._AMapSecurityConfig = {
      ...baseConfig,
      serviceHost: AMAP_SERVICE_HOST
    }
  } else if (securityJsCode) {
    // 开发环境：直接使用安全密钥
    window._AMapSecurityConfig = {
      ...baseConfig,
      securityJsCode
    }
  }
}

// 使用 AMapLoader 加载高德地图
const loadAMapScript = async (): Promise<typeof window.AMap> => {
  // 检查环境变量是否配置
  if (!AMAP_JS_API_KEY) {
    console.warn('请配置 VITE_AMAP_JS_API_KEY 环境变量')
    throw new Error('高德地图 Key 未配置')
  }

  // 配置安全策略
  setupSecurityConfig()

  try {
    const AMap = await AMapLoader.load({
      key: AMAP_JS_API_KEY,
      version: '2.0',
      plugins: ['AMap.Geocoder', 'AMap.Scale', 'AMap.ToolBar']
    })
    return AMap
  } catch (error) {
    console.error('加载高德地图失败:', error)
    throw new Error('加载高德地图失败')
  }
}

declare global {
  interface Window {
    AMap: any
    _AMapSecurityConfig?: {
      securityJsCode?: string
      serviceHost?: string
    }
  }
}

/**
 * 高德地图选点组件
 * @example
 * ```tsx
 * <AMapPicker
 *   onSelect={(result) => {
 *     console.log('选点结果:', result)
 *   }}
 * />
 * ```
 */
const AMapPicker = forwardRef<any, AMapPickerProps>(
  (
    {
      defaultLng = 113.9437,
      defaultLat = 22.5373,
      defaultZoom = 12,
      onSelect,
      disabled = false,
      height = 360
    },
    ref
  ) => {
    const mapRef = useRef<HTMLDivElement>(null)
    const mapInstanceRef = useRef<any>(null)
    const markerRef = useRef<any>(null)
    const AMapRef = useRef<any>(null)

    const [mapLoading, setMapLoading] = useState(true)
    const [searchLoading, setSearchLoading] = useState(false)
    const [mapInitialized, setMapInitialized] = useState(false)
    const [selectedLocation, setSelectedLocation] = useState<{ lat: number; lng: number } | null>(
      null
    )
    const [searchKeyword, setSearchKeyword] = useState('')
    const [searchResults, setSearchResults] = useState<
      Array<{ name: string; address: string; location: string }>
    >([])

    // 暴露方法给父组件
    useImperativeHandle(ref, () => ({
      /** 设置地图中心点 */
      setCenter: (lng: number, lat: number) => {
        if (mapInstanceRef.current) {
          mapInstanceRef.current.setCenter([lng, lat])
          updateMarker(lng, lat)
        }
      },
      /** 获取当前选中的位置 */
      getSelectedLocation: () => selectedLocation
    }))

    // 初始化高德地图
    const initMap = async () => {
      try {
        const AMap = await loadAMapScript()
        if (mapRef.current && AMap) {
          // 存储 AMap 类引用
          AMapRef.current = AMap

          const map = new AMap.Map(mapRef.current, {
            zoom: defaultZoom,
            center: [defaultLng, defaultLat]
          })

          mapInstanceRef.current = map

          // 点击地图事件
          if (!disabled) {
            map.on('click', async (e: any) => {
              const { lng, lat } = e.lnglat
              handleSelectLocation(lng, lat)
            })
          }

          setMapInitialized(true)
          setMapLoading(false)
        }
      } catch (error) {
        console.error('地图初始化失败:', error)
        message.warning('地图加载失败，请手动填写地址')
        setMapLoading(false)
      }
    }

    useEffect(() => {
      initMap()
    }, [])

    // 更新标记位置
    const updateMarker = (lng: number, lat: number) => {
      if (!mapInstanceRef.current || !AMapRef.current) {
        return
      }

      if (markerRef.current) {
        markerRef.current.setPosition([lng, lat])
      } else {
        markerRef.current = new AMapRef.current.Marker({
          position: [lng, lat],
          map: mapInstanceRef.current
        })
      }

      // 以标记为中心
      mapInstanceRef.current.setCenter([lng, lat])
    }

    // 处理选点
    const handleSelectLocation = async (lng: number, lat: number) => {
      setSelectedLocation({ lat, lng })
      updateMarker(lng, lat)

      // 逆地理编码获取地址
      const result = await reverseGeocode(lng, lat)
      if (result && onSelect) {
        onSelect(result)
      }
    }

    // GCJ-02 转 BD-09 坐标系转换
    const gcj02ToBd09 = (lng: number, lat: number): [number, number] => {
      const X_PI = (Math.PI * 3000.0) / 180.0
      const z = Math.sqrt(lng * lng + lat * lat) + 0.00002 * Math.sin(lat * X_PI)
      const theta = Math.atan2(lat, lng) + 0.000003 * Math.cos(lng * X_PI)
      const bdLng = z * Math.cos(theta) + 0.0065
      const bdLat = z * Math.sin(theta) + 0.006
      return [bdLng, bdLat]
    }

    // 逆地理编码
    const reverseGeocode = async (lng: number, lat: number): Promise<AMapPickerResult | null> => {
      try {
        const apiBase = getApiBaseUrl()
        const keyParam = isProxyMode() ? '' : `&key=${AMAP_WEB_API_KEY}`
        const response = await fetch(
          `${apiBase}/v3/geocode/regeo?location=${lng},${lat}&extensions=all&radius=1000${keyParam}`
        )
        const result: AMapRegeoResult = await response.json()

        if (result.status === '1' && result.regeocode) {
          const { addressComponent, formatted_address } = result.regeocode
          return {
            longitude: lng,
            latitude: lat,
            address: formatted_address,
            province: addressComponent.province,
            city: addressComponent.city,
            district: addressComponent.district,
            adcode: addressComponent.adcode
          }
        }
      } catch (error) {
        console.error('逆地理编码失败:', error)
      }
      return null
    }

    // 搜索地址
    const searchAddress = async () => {
      if (!searchKeyword.trim()) {
        message.warning('请输入搜索关键词')
        return
      }

      setSearchLoading(true)
      try {
        const apiBase = getApiBaseUrl()
        const keyParam = isProxyMode() ? '' : `&key=${AMAP_WEB_API_KEY}`
        const response = await fetch(
          `${apiBase}/v3/place/text?keywords=${encodeURIComponent(
            searchKeyword
          )}&citylimit=true&offset=10&page=1${keyParam}`
        )
        const result: AMapPOIResult = await response.json()

        if (result.status === '1' && result.pois && result.pois.length > 0) {
          setSearchResults(
            result.pois.map(poi => ({
              name: poi.name,
              address: poi.address || poi.name,
              location: poi.location
            }))
          )
        } else {
          message.info('未找到相关地址')
          setSearchResults([])
        }
      } catch (error) {
        console.error('搜索失败:', error)
        message.error('搜索失败')
      } finally {
        setSearchLoading(false)
      }
    }

    // 选择搜索结果
    const selectSearchResult = async (result: {
      name: string
      address: string
      location: string
    }) => {
      const [lng, lat] = result.location.split(',').map(Number)

      await handleSelectLocation(lng, lat)

      setSearchResults([])
      setSearchKeyword('')
    }

    return (
      <div>
        {/* 搜索框 */}
        <div style={{ marginBottom: 16 }}>
          <Input.Search
            placeholder="搜索地址辅助定位..."
            value={searchKeyword}
            onChange={e => setSearchKeyword(e.target.value)}
            onSearch={searchAddress}
            enterButton={
              <>
                <SearchOutlined /> 搜索
              </>
            }
            loading={searchLoading}
            disabled={disabled}
          />
          {searchResults.length > 0 && (
            <Card size="small" style={{ marginTop: 8 }}>
              {searchResults.map((result, index) => (
                <div
                  key={index}
                  style={{
                    padding: '8px 12px',
                    cursor: disabled ? 'not-allowed' : 'pointer',
                    borderBottom: '1px solid #f0f0f0',
                    transition: 'background 0.2s',
                    opacity: disabled ? 0.5 : 1
                  }}
                  onClick={() => !disabled && selectSearchResult(result)}
                  onMouseEnter={e => {
                    if (!disabled) {
                      e.currentTarget.style.background = '#f5f5f5'
                    }
                  }}
                  onMouseLeave={e => {
                    e.currentTarget.style.background = 'transparent'
                  }}
                >
                  <div style={{ fontWeight: 500 }}>{result.name}</div>
                  <div style={{ fontSize: 12, color: '#999' }}>{result.address}</div>
                </div>
              ))}
            </Card>
          )}
        </div>

        {/* 地图容器 */}
        <div
          ref={mapRef}
          style={{
            height,
            border: '1px solid #d9d9d9',
            borderRadius: 8,
            position: 'relative'
          }}
        >
          {(!mapInitialized || mapLoading) && (
            <div
              style={{
                position: 'absolute',
                top: 0,
                left: 0,
                right: 0,
                bottom: 0,
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                background: '#f5f5f5'
              }}
            >
              <Space direction="vertical" align="center">
                <LoadingOutlined style={{ fontSize: 24 }} />
                <span>地图加载中...</span>
              </Space>
            </div>
          )}
        </div>
      </div>
    )
  }
)

AMapPicker.displayName = 'AMapPicker'

export default AMapPicker
